    if (hit < H && T > 0.6 + hit * 0.3) { hit++; const last = hit === H; const at = last ? tgt.clone() : c.ground(tgt.clone().add(V(R(10), 0, R(10)))); const m = o.mk(); const from = at.clone().add(V(0, 16, 0)).addScaledVector(fl, -5); fly(c, m, { from, vel: at.clone().sub(from).normalize().multiplyScalar(40), r: 1, life: 1, noLook: true, tick: () => { m.scale.setScalar(last ? 6 : 3); m.rotation.set(Math.PI / 2, 0, 0); }, onEnd: p => { const q = c.ground(p.clone()).add(V(0, 0.5, 0)); boom(c, q, o.col, last ? 10 : 5, { star: 0xffffff }); cracks(g, q, 10, 8); c.hitR(q, last ? 13 : 6, last ? 2.2 : 0.5, { kb: 8, up: 6 }); c.shake(0.7); sfx(c, 'boom', 0.7); if (last) word(g, q.clone().add(V(0, 10, 0)), o.word, hex(o.col), 4.5, 1.2); } }); }
